use std::{fs,io::{self,Read,Write},path::Path};
pub fn transfer(input:&mut impl Read,output:&mut impl Write,total:u64,mut progress:impl FnMut(u64)->io::Result<()>)->io::Result<()>{let mut buffer=vec![0;1<<20];let mut done=0;loop{progress(done)?;let n=input.read(&mut buffer)?;if n==0{break;}if done+n as u64>total{return Err(io::Error::other("Source grew during copy"));}output.write_all(&buffer[..n])?;done+=n as u64;}if done!=total{return Err(io::Error::other("Source was truncated during copy"));}progress(done)}
pub fn verify(a:&Path,b:&Path,total:u64,mut progress:impl FnMut(u64)->io::Result<()>)->io::Result<()>{let mut a=fs::File::open(a)?;let mut b=fs::File::open(b)?;let mut x=vec![0;1<<20];let mut y=vec![0;1<<20];let mut done=0;while done<total{progress(done)?;let n=((total-done) as usize).min(x.len());a.read_exact(&mut x[..n])?;b.read_exact(&mut y[..n])?;if x[..n]!=y[..n]{return Err(io::Error::other("Copied package verification failed"));}done+=n as u64;}if a.read(&mut x[..1])?!=0||b.read(&mut y[..1])?!=0{return Err(io::Error::other("Package size changed"));}progress(done)}
#[cfg(test)]mod tests{use super::*;
 #[test]fn verification_detects_corruption_and_growth(){let root=std::env::temp_dir().join(format!("titan-verify-{}",std::process::id()));fs::create_dir_all(&root).unwrap();let a=root.join("a");let b=root.join("b");fs::write(&a,b"abc").unwrap();fs::write(&b,b"abc").unwrap();verify(&a,&b,3,|_|Ok(())).unwrap();fs::write(&b,b"abd").unwrap();assert!(verify(&a,&b,3,|_|Ok(())).is_err());fs::write(&b,b"abcd").unwrap();assert!(verify(&a,&b,3,|_|Ok(())).is_err());assert!(verify(&a,&a,3,|_|Err(io::Error::other("cancel"))).is_err());assert_eq!(fs::read(a).unwrap(),b"abc");fs::remove_dir_all(root).unwrap();}

 #[test]fn interrupted_and_truncated_transfers_fail(){let mut dst=Vec::new();assert!(transfer(&mut &b"abc"[..],&mut dst,4,|_|Ok(())).is_err());let mut dst=Vec::new();assert!(transfer(&mut &b"abc"[..],&mut dst,3,|_|Err(io::Error::other("cancel"))).is_err());assert!(dst.is_empty());}
 #[test]fn copy_reports_exact_bytes(){let mut dst=Vec::new();let mut count=0;transfer(&mut &b"abc"[..],&mut dst,3,|n|{count=n;Ok(())}).unwrap();assert_eq!(dst,b"abc");assert_eq!(count,3);}
}
